const anonKey = '[REDACTED_SUPABASE_ANON_KEY]';
const botToken = '[REDACTED_TELEGRAM_BOT_TOKEN]';
const anthropicKey = '[REDACTED_ANTHROPIC_KEY]';

async function logSystemError(sellerId, source, message, context) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/system_errors',
      headers: { apikey: anonKey, Authorization: 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
      body: JSON.stringify({ seller_id: sellerId || null, source: 'n8n:' + source, error_message: String(message).slice(0, 500), context: context || null })
    });
  } catch (e) {}
}

async function notifySellerBoth(chatId, text) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.telegram.org/bot' + botToken + '/sendMessage',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ chat_id: chatId, text, parse_mode: 'HTML' })
    });
  } catch (e) {}
  try {
    const plainText = (text || '').replace(/<\/?[a-z][^>]*>/gi, '');
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/seller_web_chat_log',
      headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
      body: JSON.stringify({ seller_id: chatId, role: 'ahmad', message: plainText })
    });
  } catch (e) {}
}

const overallResults = { sellersProcessed: 0, debug: [] };

let sellersList = [];
try {
  sellersList = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/sellers?select=chat_id,business_name_location,business_category',
    headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
  }) || [];
} catch(e) {
  overallResults.debug.push('Could not load sellers list: ' + e.message);
}

for (const seller of sellersList) {
  const chatId = seller.chat_id;
  if (!chatId) continue;

  try {
    let lang = 'english';
    try {
      const prefs = await this.helpers.httpRequest({
        method: 'GET',
        url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/seller_preferences?chat_id=eq.' + chatId + '&select=language&limit=1',
        headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
      });
      if (prefs && prefs.length > 0) lang = prefs[0].language || 'english';
    } catch(e) { await logSystemError.call(this, chatId, 'Daily Summary (language pref)', e.message); }

    let salesConfig = {};
    try {
      const configResp = await this.helpers.httpRequest({
        method: 'GET',
        url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/seller_sales_config?chat_id=eq.' + chatId + '&select=*&limit=1',
        headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
      });
      if (configResp && configResp.length > 0) salesConfig = configResp[0];
    } catch(e) { await logSystemError.call(this, chatId, 'Daily Summary (sales config)', e.message); }
    const currencyLabel = salesConfig.currency_label || 'USD';
    const businessDesc = seller.business_name_location || 'this business';

    const now = new Date();
    const todayBaghdad = new Date(now.getTime() + (3 * 60 * 60 * 1000));
    const yesterdayStart = new Date(todayBaghdad);
    yesterdayStart.setDate(yesterdayStart.getDate() - 1);
    yesterdayStart.setHours(0, 0, 0, 0);
    const yesterdayEnd = new Date(todayBaghdad);
    yesterdayEnd.setHours(0, 0, 0, 0);

    const yesterdayStartISO = new Date(yesterdayStart.getTime() - (3 * 60 * 60 * 1000)).toISOString();
    const yesterdayEndISO = new Date(yesterdayEnd.getTime() - (3 * 60 * 60 * 1000)).toISOString();
    const threeDaysAgo = new Date(now.getTime() - (3 * 24 * 60 * 60 * 1000)).toISOString();

    let yesterdayOrders = [];
    let pendingOrders = [];
    let silentCustomers = [];
    let newCustomers = [];
    let totalCustomers = 0;
    let yesterdayRevenue = 0;
    let totalOrders = 0;
    let warmCustomers = 0;

    try {
      const ordersRes = await this.helpers.httpRequest({
        method: 'GET',
        url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/orders?seller_id=eq.' + chatId + '&created_at=gte.' + yesterdayStartISO + '&created_at=lt.' + yesterdayEndISO + '&select=phone,product_name,order_total,order_status',
        headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
      });
      yesterdayOrders = ordersRes || [];
      yesterdayRevenue = yesterdayOrders.reduce((sum, o) => sum + (o.order_total || 0), 0);
    } catch(e) { await logSystemError.call(this, chatId, 'Daily Summary (yesterday orders)', e.message); }

    try {
      const pendingRes = await this.helpers.httpRequest({
        method: 'GET',
        url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/orders?seller_id=eq.' + chatId + '&order_status=eq.PENDING&select=phone,product_name,order_total,created_at&order=created_at.desc&limit=20',
        headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
      });
      pendingOrders = pendingRes || [];
    } catch(e) { await logSystemError.call(this, chatId, 'Daily Summary (pending orders)', e.message); }

    try {
      const customersRes = await this.helpers.httpRequest({
        method: 'GET',
        url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/customers?seller_id=eq.' + chatId + '&select=phone,name,list_status,last_reply_date,created_at&limit=500',
        headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
      });
      const allCustomers = customersRes || [];
      totalCustomers = allCustomers.length;
      warmCustomers = allCustomers.filter(c => c.list_status === 'WARM').length;
      silentCustomers = allCustomers.filter(c => !c.last_reply_date || new Date(c.last_reply_date) < new Date(threeDaysAgo));
      newCustomers = allCustomers.filter(c => c.created_at && c.created_at >= yesterdayStartISO && c.created_at < yesterdayEndISO);
    } catch(e) { await logSystemError.call(this, chatId, 'Daily Summary (customers)', e.message); }

    try {
      const totalOrdersRes = await this.helpers.httpRequest({
        method: 'GET',
        url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/orders?seller_id=eq.' + chatId + '&select=id',
        headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
      });
      totalOrders = (totalOrdersRes || []).length;
    } catch(e) { await logSystemError.call(this, chatId, 'Daily Summary (total orders)', e.message); }

    if (totalCustomers === 0 && totalOrders === 0) continue;

    const yesterdayDate = yesterdayStart.toLocaleDateString('en-GB');
    const curSuffix = currencyLabel ? ' ' + currencyLabel : '';

    const dataSummary = `
BUSINESS DATA FOR DAILY SUMMARY:
Date: ${yesterdayDate}
Total customers in system: ${totalCustomers}
Active customers (WARM): ${warmCustomers}

YESTERDAY'S ORDERS (${yesterdayDate}):
Count: ${yesterdayOrders.length}
Revenue: ${yesterdayRevenue.toLocaleString()}${curSuffix}
Orders: ${yesterdayOrders.length > 0 ? yesterdayOrders.map(o => `- ${o.phone}: ${o.product_name || 'product'} — ${(o.order_total || 0).toLocaleString()}${curSuffix}`).join('\n') : 'No orders yesterday'}

PENDING ORDERS (need attention):
Count: ${pendingOrders.length}
${pendingOrders.length > 0 ? pendingOrders.slice(0, 5).map(o => `- ${o.phone}: ${o.product_name || 'product'} — ${(o.order_total || 0).toLocaleString()}${curSuffix}`).join('\n') : 'No pending orders'}

SILENT CUSTOMERS (no reply 3+ days):
Count: ${silentCustomers.length}
${silentCustomers.length > 0 ? silentCustomers.slice(0, 5).map(c => `- ${c.phone}${c.name ? ' (' + c.name + ')' : ''}`).join('\n') : 'None'}

NEW CUSTOMERS YESTERDAY:
Count: ${newCustomers.length}
${newCustomers.length > 0 ? newCustomers.map(c => `- ${c.phone}${c.name ? ' (' + c.name + ')' : ''}`).join('\n') : 'None'}

TOTAL ALL-TIME ORDERS: ${totalOrders}
`;

    const langInstruction = lang === 'english'
      ? 'Write ONLY in English.'
      : lang === 'kurdish'
      ? 'Write ONLY in Kurdish Sorani.'
      : lang === 'arabic'
      ? 'اكتب بالعربي العراقي الدارج فقط.'
      : `Write ONLY in ${lang}.`;

    const claudeResponse = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.anthropic.com/v1/messages',
      headers: { 'x-api-key': anthropicKey, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 600,
        system: `You are Sparkly, an AI assistant sending a daily morning business summary to the owner of ${businessDesc}.

${langInstruction}

Write a friendly, natural morning summary — like a smart assistant briefing their boss. Use emojis naturally. Keep it concise but complete.

Structure:
1. Good morning greeting with date
2. Yesterday's performance (orders + revenue) — be encouraging if good, motivating if slow
3. Pending orders that need attention (if any)
4. Silent customers count + brief advice (if any)
5. New customers yesterday (if any)
6. One short motivational closing line

IMPORTANT:
- Plain text only, no markdown
- Natural and warm tone
- If yesterday had 0 orders, be encouraging not negative
- Max 20 lines total
- Don't list more than 5 items in any section`,
        messages: [{ role: 'user', content: dataSummary }]
      })
    });

    const summary = claudeResponse.content[0].text.trim();

    await notifySellerBoth.call(this, chatId, summary);

    overallResults.sellersProcessed++;

    try {
      const digestConfigResp = await this.helpers.httpRequest({
        method: 'GET',
        url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/ad_daily_digest_config?chat_id=eq.' + chatId + '&select=enabled,metrics&limit=1',
        headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
      });
      const digestConfig = digestConfigResp && digestConfigResp[0];

      if (digestConfig && digestConfig.enabled && Array.isArray(digestConfig.metrics) && digestConfig.metrics.length > 0) {
        const adConfigResp3 = await this.helpers.httpRequest({
          method: 'GET',
          url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/seller_ad_config?chat_id=eq.' + chatId + '&select=ad_account_id,meta_ads_token,enabled&limit=1',
          headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
        });
        const adConfig3 = adConfigResp3 && adConfigResp3[0];

        if (adConfig3 && adConfig3.enabled === true && adConfig3.ad_account_id && adConfig3.meta_ads_token) {
          const adAccountPath3 = adConfig3.ad_account_id.startsWith('act_') ? adConfig3.ad_account_id : 'act_' + adConfig3.ad_account_id;
          const yesterdayIsoDate = yesterdayStart.toISOString().split('T')[0];

          const insightsResp3 = await this.helpers.httpRequest({
            method: 'GET',
            url: 'https://graph.facebook.com/v19.0/' + adAccountPath3 + '/insights?level=account&fields=spend,clicks,ctr,cpc,cpm,reach,frequency,actions,action_values&time_range=' + encodeURIComponent(JSON.stringify({ since: yesterdayIsoDate, until: yesterdayIsoDate })) + '&access_token=' + adConfig3.meta_ads_token
          });
          const row3 = insightsResp3 && insightsResp3.data && insightsResp3.data[0];

          if (row3) {
            const purchaseActionTypes3 = ['purchase', 'offsite_conversion.fb_pixel_purchase', 'omni_purchase', 'onsite_conversion.purchase', 'onsite_web_purchase', 'onsite_app_purchase', 'onsite_web_app_purchase'];
            const purchases3 = ((row3.actions || []).find(a => purchaseActionTypes3.includes(a.action_type)) || {}).value;
            const purchaseValue3 = ((row3.action_values || []).find(a => purchaseActionTypes3.includes(a.action_type)) || {}).value;
            const msgStarts3 = ((row3.actions || []).find(a => a.action_type === 'onsite_conversion.messaging_conversation_started_7d') || {}).value;
            const spend3 = parseFloat(row3.spend || 0);
            const purchasesNum = purchases3 ? parseFloat(purchases3) : 0;
            const msgStartsNum = msgStarts3 ? parseFloat(msgStarts3) : 0;

            const monetaryDigestMetrics = ['spend', 'cpc', 'cpm', 'cost_per_message', 'cost_per_sale', 'cpa'];
            const digestLines = digestConfig.metrics.map(m => {
              const unit = monetaryDigestMetrics.includes(m) && currencyLabel ? ' ' + currencyLabel : '';
              if (m === 'spend') return `Spend: ${spend3.toLocaleString()}${unit}`;
              if (m === 'clicks') return `Clicks: ${row3.clicks || 0}`;
              if (m === 'ctr') return `CTR: ${row3.ctr || 0}%`;
              if (m === 'cpc') return `CPC: ${row3.cpc || 0}${unit}`;
              if (m === 'cpm') return `CPM: ${row3.cpm || 0}${unit}`;
              if (m === 'reach') return `Reach: ${row3.reach || 0}`;
              if (m === 'frequency') return `Frequency: ${row3.frequency || 0}`;
              if (m === 'messages_started') return `Messages started: ${msgStartsNum}`;
              if (m === 'actions' || m === 'purchases') return `Purchases: ${purchasesNum}`;
              if (m === 'cpa' || m === 'cost_per_sale') return purchasesNum > 0 ? `Cost per sale: ${(spend3 / purchasesNum).toFixed(2)}${unit}` : `Cost per sale: no sales yesterday`;
              if (m === 'cost_per_message') return msgStartsNum > 0 ? `Cost per message: ${(spend3 / msgStartsNum).toFixed(2)}${unit}` : `Cost per message: no messages started yesterday`;
              if (m === 'roas') return (purchaseValue3 && spend3 > 0) ? `ROAS: ${(parseFloat(purchaseValue3) / spend3).toFixed(2)}x` : `ROAS: no purchase value data yesterday`;
              return null;
            }).filter(Boolean);

            if (digestLines.length > 0) {
              const digestText = `📊 Ad metrics for ${yesterdayDate}:\n\n${digestLines.join('\n')}`;
              await notifySellerBoth.call(this, chatId, digestText);
            }
          }
        }
      }
    } catch (digestErr) {
      overallResults.debug.push('Ad daily digest error for seller ' + chatId + ': ' + digestErr.message);
    }
  } catch(e) {
    overallResults.debug.push('Seller ' + chatId + ' processing error: ' + e.message);
  }
}

return [{ json: { success: true, sellersProcessed: overallResults.sellersProcessed, results: overallResults } }];
